function recoveryBusy(){return !!game.recoveryPending||!!game.recovery&&!game.recovery.done}
function clearRecovery(){game.recovery=null;game.recoveryPending=null;game.afterRecovery=null;}
function recoveryBones(rig){return [rig.model,rig.pelvis,rig.torso,rig.head,...rig.legs.flatMap(l=>[l.hip,l.knee,l.ankle]),...rig.arms.flatMap(a=>[a.shoulder,a.elbow,a.wrist,a.thumb,a.thumbTip,...a.fingers.flat()])];}
function captureRecoveryActor(rig,x,z,yaw,ballCarrier,delay){setRigVisible(rig,true);return {rig,x,z,yaw,ballCarrier,delay,side:ballCarrier?1:-1,snapshot:recoveryBones(rig).map(bone=>({bone,position:bone.position.clone(),quaternion:bone.quaternion.clone(),scale:bone.scale.clone()}))};}
function scheduleRecovery(delay=.26){if(game.recovery||game.recoveryPending)return;game.recoveryPending={remaining:delay};playing=true;}
function beginRecovery(type='contact'){if(game.recovery)return;const entries=[];if(type==='punt'&&game.special?.tackle){const f=game.special.sample(),i=game.special.coverage.indexOf(game.special.tackle.defender),rigs=[qbRig,receivers[2],receivers[3],receivers[4]];entries.push(captureRecoveryActor(defensiveBacks[0],f.actors.returner.x,f.actors.returner.z,f.actors.returner.yaw,true,0));entries.push(captureRecoveryActor(rigs[i],f.actors.coverage[i].x,f.actors.coverage[i].z,f.actors.coverage[i].yaw,false,.12));}else if(game.qbTackle){const k=game.qbTackle,age=Math.max(0,time-k.start),travel=(1-Math.exp(-3*age))/3,pos={x:k.carrier.x+k.velocity.x*travel,z:k.carrier.z+k.velocity.z*travel};entries.push(captureRecoveryActor(qbRig,pos.x,pos.z,k.yaw,true,0));entries.push(captureRecoveryActor(k.rusher===undefined?defensiveBacks[k.defender-1]:rushers[k.rusher],pos.x-.35*Math.sin(k.yaw),pos.z-.35*Math.cos(k.yaw),k.yaw,false,.12));}else if(defenseSim.tackle){const k=defenseSim.tackle,carrier=game.carrier===0?qbRig:receivers[selectedNumber-1],tackler=k.rusher===undefined?defensiveBacks[k.defender-1]:rushers[k.rusher],state=k.rusher===undefined?defenseSim.db[k.defender-1]:defenseSim.rush[k.rusher];entries.push(captureRecoveryActor(carrier,k.carrier.x,k.carrier.z,k.yaw,true,0));entries.push(captureRecoveryActor(tackler,state.pos.x,state.pos.z,k.yaw,false,.12));}if(!entries.length)return;game.recoveryPending=null;game.recovery={elapsed:0,entries,done:false,ballStart:ball.position.clone(),ballQ:ball.quaternion.clone()};playing=false;game.input.clear();holdingNumber=0;$('contactInfo').textContent='Release wrap · plant a hand · step through · stand';}
function tickRecovery(dt){if(game.recoveryPending){game.recoveryPending.remaining-=dt;if(game.recoveryPending.remaining<=0)beginRecovery();}if(!game.recovery&&game.mode==='practice'&&!game.special&&defenseSim.tackle?.ground>.55)beginRecovery();if(!game.recovery)return false;if(!game.recovery.done){game.recovery.elapsed+=dt;game.recovery.done=game.recovery.entries.every(e=>sampleGetUp(game.recovery.elapsed,e).done);}if(game.recovery.done&&game.afterRecovery){const action=game.afterRecovery;game.afterRecovery=null;if(action.type==='next')nextDown();else if(action.type==='conversion')chooseConversion(action.points);else if(action.type==='play')choosePlay(action.playType,action.gap);else if(action.type==='kick')beginSpecialTeams(action.kickType);else resetPlay();return true;}return true;}
function renderRecovery(){const r=game.recovery;let carrierPose=null;for(const entry of r.entries){const pose=sampleGetUp(r.elapsed,entry),blend=smooth(T.MathUtils.clamp((r.elapsed-entry.delay)/.35,0,1));poseSpecialActor(entry.rig,pose);if(blend<1){for(const item of entry.snapshot){const endPosition=item.bone.position.clone(),endQ=item.bone.quaternion.clone(),endScale=item.bone.scale.clone();item.bone.position.copy(item.position).lerp(endPosition,blend);item.bone.quaternion.copy(item.quaternion).slerp(endQ,blend);item.bone.scale.copy(item.scale).lerp(endScale,blend)}entry.rig.model.updateWorldMatrix(true,true);updateSurfaces(entry.rig.surfaces)}if(entry.ballCarrier)carrierPose=pose;const receiverEntry=receivers.find(w=>w.model===entry.rig.model);if(receiverEntry)receiverEntry.label.position.copy(entry.rig.model.position).add(new T.Vector3(0,2.2,0));}if(carrierPose?.ballHoldPoint){const p=carrierPose.ballHoldPoint;ball.position.copy(r.ballStart).lerp(new T.Vector3(p.x,p.y,p.z),smooth(T.MathUtils.clamp(r.elapsed/.35,0,1)));ball.quaternion.copy(r.ballQ).slerp(new T.Quaternion().setFromAxisAngle(new T.Vector3(0,0,1),.65),smooth(T.MathUtils.clamp(r.elapsed/.55,0,1)));}else ball.position.copy(r.ballStart);$('phase').textContent=r.done?'Players up · ready for the next play':'Get up · '+(carrierPose?.phase||'recover');$('clock').textContent=time.toFixed(2)+' s · '+(r.done?'Recovered':'Getting up');if(game.mode==='practice'){$('play').textContent=r.done?'New play':'Getting up…';$('play').disabled=!r.done}$('contactInfo').textContent=r.done?'Both players standing · contact cleared':'Release wrap · hand plant · knee under · push to stand';}

function checkSpecialTeams(){const f=game.special.sample();if(!f.outcome||game.specialResolved)return;game.specialResolved=true;const o=f.outcome;if(game.match){game.match.resolveKick({...o,type:game.specialKickType,distance:o.distance??o.puntYards,returnTouchdown:o.opponentTouchdown});game.deadTime=time;playing=false;$('chargeText').textContent=game.match.message;updateGameHUD();if(game.match.phase==='over')showFinal()}else{game.specialSummary=f.type==='punt'?Math.round(o.puntYards)+'-yard punt · '+Math.round(o.returnYards||0)+'-yard return':o.made?'FIELD GOAL MADE · 3 points (practice)':'Field goal missed (practice)';playing=false;$('chargeText').textContent=game.specialSummary;updateSpecialOptions()}if(game.special.tackle&&game.match?.phase!=='over')beginRecovery('punt')}

function advanceRunner(dt,input){const sprint=(isDefending()?true:game.input.has('Shift'))&&game.stamina>1;if(sprint)game.stamina=Math.max(0,game.stamina-25*dt);else game.stamina=Math.min(100,game.stamina+14*dt);let control={...input};if(game.playType==='run'&&game.runGuided){if(input.steer)game.runGuided=false;else if(input.throttle>0&&game.runGuide){let goal=game.runGuide[game.runGuideIndex];if(Math.hypot(goal.x-game.runner.x,goal.z-game.runner.z)<.65&&game.runGuideIndex<game.runGuide.length-1)goal=game.runGuide[++game.runGuideIndex];const angle=Math.atan2(goal.x-game.runner.x,goal.z-game.runner.z),delta=Math.atan2(Math.sin(angle-game.runner.yaw),Math.cos(angle-game.runner.yaw));control.steer=T.MathUtils.clamp(delta/(4.9*.16),-1,1);if(game.runner.z>3.3)game.runGuided=false}}integrateRunner(game.runner,control,dt,sprint?9.8:8.7);if(game.carrier===0)blockQBPath(game.runner);game.track.push({...game.runner,t:time+dt});if(game.carrier===0){game.qbRunner=game.runner;game.qbOffset.set(game.runner.x,0,game.runner.z+.95);game.qbVelocity.set(game.runner.vx,0,game.runner.vz)}}
