function animateQBMovement(){const speed=game.qbVelocity.length(),gait=runGait(game.qbRunner?.distance||0,speed),yaw=game.qbRunner?.yaw||0,forward=new T.Vector3(Math.sin(yaw),0,Math.cos(yaw)),right=new T.Vector3(forward.z,0,-forward.x),phase=gait.angle,weight=Math.min(1,speed/5.8);player.position.y=-.18+gait.bob;player.rotation.set(0,yaw,0);pelvis.rotation.set(gait.lean*.45,gait.hipYaw,gait.hipRoll);torso.rotation.set(gait.lean,gait.shoulderYaw,gait.shoulderRoll);const look=receivers[selectedNumber-1].model.position.clone().sub(player.position);head.rotation.set(0,T.MathUtils.clamp(Math.atan2(Math.sin(Math.atan2(look.x,look.z)-yaw),Math.cos(Math.atan2(look.x,look.z)-yaw)),-.7,.7),0);player.updateWorldMatrix(true,true);for(let i=0;i<2;i++){const side=i===RIGHT?-1:1,cycle=phase+i*Math.PI,foot=player.position.clone().addScaledVector(forward,.28*Math.sin(cycle)*weight).addScaledVector(right,side*.12);foot.y=.1+.26*Math.max(0,Math.cos(cycle))**.8*weight+.03*gait.flight;const pole=player.position.clone().addScaledVector(forward,.35).addScaledVector(right,side*.13).setY(.8);placeLeg(legs[i],foot,pole,yaw)}const center=player.position.clone().addScaledVector(forward,.23).addScaledVector(right,-.08).setY(1.34),wristQ=new T.Quaternion().setFromEuler(new T.Euler(-.38,yaw,.12)),wristTarget=center.clone().sub(grip.clone().applyQuaternion(wristQ));armIK(arms[RIGHT],wristTarget,player.localToWorld(new T.Vector3(-.38,1.05,.05)));arms[RIGHT].wrist.quaternion.copy(arms[RIGHT].wrist.parent.getWorldQuaternion(new T.Quaternion()).invert().multiply(wristQ));armIK(arms[LEFT],game.caught&&game.carrier===0?player.position.clone().addScaledVector(right,.28).addScaledVector(forward,-.34*Math.sin(phase)*weight).setY(1.1+.08*Math.cos(phase)):center.clone().addScaledVector(right,.10).addScaledVector(forward,.02).add(new T.Vector3(0,-.035,0)),player.localToWorld(new T.Vector3(.38,1.12,.08)));player.updateWorldMatrix(true,true);updateSurfaces()}

function setThrowError(){const nearest=Math.min(...defenseSim.rush.map(r=>Math.hypot(r.pos.x-game.qbOffset.x,r.pos.z-(game.qbOffset.z-.95)))),pressure=T.MathUtils.clamp((2.3-nearest)/2.3,0,1),skill=game.match?.difficulty==='easy'?.07:game.match?.difficulty==='hard'?.22:.13,range=Math.hypot(catchPoint.x-releasePos.x,catchPoint.z-releasePos.z),error=skill+range*.008+pressure*.75+game.qbVelocity.length()*.11,random=()=>game.match?game.match.random():rand();const elevation=launchAngle;game.miss.set((random()+random()-1)*error,0,(random()+random()-1)*error);launchVelocity.addScaledVector(game.miss,1/FLIGHT_TIME);launchVelocity.y=Math.hypot(launchVelocity.x,launchVelocity.z)*Math.tan(elevation);launchVelocity.clampLength(0,MAX_PASS_SPEED);launchAngle=Math.atan2(launchVelocity.y,Math.hypot(launchVelocity.x,launchVelocity.z));flightAxis.copy(launchVelocity).normalize();launchQ.setFromUnitVectors(new T.Vector3(0,1,0),flightAxis);buildAirPursuit();}
function endGamePlay(kind,point,pass=passArmed&&game.caught&&game.carrier!==0){if(game.match.phase!=='live')return;const yards=point?point.z/.9144:0;game.match.finish({kind,yards,pass});game.deadTime=time;if(game.match.phase!=='over'&&(game.qbTackle||defenseSim.tackle))scheduleRecovery(game.qbTackle?1.28:.26);holdingNumber=0;game.input.clear();$('chargeText').textContent=game.match.message;updateGameHUD();if(game.match.phase==='over'){playing=false;showFinal()}}
function checkLivePlay(){const g=game.match;if(g.phase!=='live')return;if(game.special){checkSpecialTeams();return}if(passArmed&&time>=THROW_TIME&&!game.attemptRecorded){g.thrown();game.attemptRecorded=true}const qb=new T.Vector3(game.qbOffset.x,0,game.qbOffset.z-.95);if(!game.caught&&(!passArmed||time<THROW_TIME)&&(g.spot+qb.z/.9144<=-10||Math.abs(qb.x)>24.38)){endGamePlay(g.spot+qb.z/.9144<=0?'safety':'out',qb,false);return}if(!game.caught&&(!passArmed||time<THROW_TIME)&&time>.9){const r=[...defenseSim.rush,...defenseSim.db].find(r=>inTackleReach(r,qb));if(r){const velocity=collisionMomentum({x:game.qbVelocity.x,z:game.qbVelocity.z},r.vel,94,r.mass);game.qbTackle={start:time,carrier:{x:qb.x,z:qb.z},velocity,yaw:Math.atan2(r.vel.x,r.vel.z),duration:.58,age:0,fall:0,ground:0,kind:'front',...(defenseSim.rush.includes(r)?{rusher:r.id}:{defender:r.id})};endGamePlay('sack',qb,false);return}}
if(game.deflection){if(ball.position.y<=.13&&time-game.deflection.start>.08)endGamePlay('incomplete',null,false);return;}
if(passArmed&&!game.caught&&time>THROW_TIME+.08&&time<=CATCH_TIME+.06){const hit=contestPass(game.previousBall||ball.position,ball.position,defenseSim.db,{time,release:THROW_TIME,random:()=>g.random(),attempted:game.passAttempts||(game.passAttempts=new Set()),manualIndex:defenseSim.userControl?.index??-1,manualAction:!!defenseSim.userControl?.action});game.previousBall=ball.position.clone();if(hit){game.defensePlay={...hit,start:time};if(hit.kind==='interception'){game.intDefender=hit.d.id;endGamePlay('interception',new T.Vector3(hit.point.x,hit.point.y,hit.point.z),false);return;}game.missed=true;defenseSim.catchTime=Infinity;game.deflection={start:time,pos:new T.Vector3(hit.point.x,hit.point.y,hit.point.z),velocity:new T.Vector3(launchVelocity.x*.22,1.1,-launchVelocity.z*.17)};$('chargeText').textContent='PASS BROKEN UP · swatted away';return;}if(Math.abs(ball.position.x)>24.38||ball.position.y<.09){game.missed=true;endGamePlay('incomplete',null,false);return}}
if(passArmed&&!game.caught&&time>=CATCH_TIME){if(game.missed){endGamePlay('incomplete',null,false);return}beginRun(selectedNumber)}
if(game.caught){const point=defenseSim.tackle?new T.Vector3(defenseSim.tackle.carrier.x,0,defenseSim.tackle.carrier.z):controlledRoute(time).point;if(game.match.spot+point.z/.9144>=100){endGamePlay('touchdown',point);return}if(game.match.spot+point.z/.9144<=-10){endGamePlay('safety',point);return}if(Math.abs(point.x)>24.38){endGamePlay('out',point);return}if(defenseSim.tackle?.ground>.30){endGamePlay('tackle',point);return}}
if(time>16&&!game.caught){endGamePlay('sack',qb,false)}}
function applyGameContact(){if(game.recovery)return;const k=game.qbTackle;if(k){k.age=Math.max(0,time-k.start);k.fall=smooth(T.MathUtils.clamp((k.age-.18)/k.duration,0,1));k.ground=smooth(T.MathUtils.clamp((k.age-.18-k.duration)/.4,0,1));const travel=(1-Math.exp(-3.0*k.age))/3.0,pos={x:k.carrier.x+k.velocity.x*travel,z:k.carrier.z+k.velocity.z*travel};fallRig(qbRig,pos,k);updateSurfaces(continuous);ball.position.copy(grip);arms[RIGHT].wrist.localToWorld(ball.position);const tackler=k.rusher===undefined?defensiveBacks[k.defender-1]:rushers[k.rusher],at={x:pos.x-.35*Math.sin(k.yaw),z:pos.z-.35*Math.cos(k.yaw)};fallRig(tackler,at,k,true);const waist=player.localToWorld(new T.Vector3(0,.92,.05));if(k.age<.80)for(let i=0;i<2;i++)armIK(tackler.arms[i],tackler.arms[i].wrist.getWorldPosition(new T.Vector3()).lerp(waist.clone().add(new T.Vector3(i?.12:-.12,0,0)),1-smooth(T.MathUtils.clamp((k.age-.35)/.45,0,1))),tackler.model.localToWorld(new T.Vector3(i?.3:-.3,.9,.05)));tackler.model.updateWorldMatrix(true,true);updateSurfaces(tackler.surfaces);}
if(game.intDefender){const rig=defensiveBacks[game.intDefender-1],center=rig.model.localToWorld(new T.Vector3(0,1.15,.18));if(game.defensePlay?.kind==='interception'){const p=game.defensePlay.point;center.lerp(new T.Vector3(p.x,p.y,p.z),1-smooth(T.MathUtils.clamp((time-game.defensePlay.start)/.26,0,1)));}for(let i=0;i<2;i++)armIK(rig.arms[i],center.clone().add(new T.Vector3(i?.08:-.08,-.04,0)),rig.model.localToWorld(new T.Vector3(i?.28:-.28,1.02,0)));rig.model.updateWorldMatrix(true,true);updateSurfaces(rig.surfaces);ball.position.copy(center)}if(game.match.phase==='dead'||game.match.phase==='over')$('phase').textContent=game.match.message;}
function refreshCoverage(force=false){const g=game.mode==='match'?game.match:null,key=g?[g.log.length,g.down,g.spot.toFixed(3),g.conversion||'normal'].join('|'):null;if(force||!g||game.coverageMatch!==g||game.coverageKey!==key){game.coverageSeed=Math.floor((g?g.random():rand())*4294967296)>>>0;game.coverageMatch=g;game.coverageKey=key}for(const receiver of receivers){let state=(game.coverageSeed+Math.imul(receiver.number,104729))>>>0;const random=()=>{state=(Math.imul(state,1664525)+1013904223)>>>0;return state/4294967296};receiver.runProfile={pace:.95+random()*.10,acceleration:.90+random()*.20,cut:.85+random()*.30,releaseDelay:random()*.14};}defenseSim.seed=game.coverageSeed;defenseSim.playType=game.playType==='run'?'run':'pass';defenseSim.runGap=game.runGap;}
